// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v <= type(uint256).max / _tos.length);
        vm.assume(from != address(0));
        bool ret = c.transfer(from, address(0), _tos, v);
        assertTrue(ret);
    }
}
